def solve(rows):
    on_time_rows = [row for row in rows if row['result'] == 'on_time']
    if not on_time_rows:
        return None

    depot_packages_distance = {}
    for row in on_time_rows:
        depot = row['depot']
        packages = row['packages']
        distance_km = row['distance_km']
        depot_packages_distance[depot] = depot_packages_distance.get(depot, 0) + packages * distance_km

    max_depot = None
    max_total = 0

    for depot, total in depot_packages_distance.items():
        if total > max_total or (total == max_total and depot < max_depot):
            max_total = total
            max_depot = depot

    return max_depot
```

