def solve(rows):
    balance = 0
    min_balance = 0
    min_day = None

    for row in sorted(rows, key=lambda x: (x['day'], x['trip_id'])):
        if row['result'] == 'on_time':
            balance += row['packages']
        elif row['result'] == 'aborted':
            balance -= row['packages']

        if balance != 0:
            if (min_balance == 0 and balance < 0) or (balance < min_balance):
                min_balance = balance
                min_day = row['day']
            elif balance == min_balance:
                if row['day'] < min_day:
                    min_day = row['day']

    if min_balance == 0:
        return [0, None]
    else:
        return [min_balance, min_day]
