def solve(rows):
    # Sort rows by distance_km descending, then day ascending, then trip_id ascending
    sorted_rows = sorted(rows, key=lambda x: (-x['distance_km'], x['day'], x['trip_id']))

    # Initialize variables
    top_trip_ids = []
    current_balance = 0
    min_balance = float('inf')
    min_day = None

    for row in sorted_rows:
        if row['result'] in ['on_time', 'aborted']:
            if row['result'] == 'on_time':
                current_balance += row['packages']
            else:
                current_balance -= row['packages']

            if current_balance < min_balance:
                min_balance = current_balance
                min_day = row['day']

            top_trip_ids.append(row['trip_id'])

            # Keep only top 3 trip_ids
            if len(top_trip_ids) > 3:
                top_trip_ids.pop(0)

    if not top_trip_ids:
        return []
    else:
        return top_trip_ids
