                    start_day = start_day
                current_consecutive = 1

    if current_consecutive > max_consecutive:
        max_consecutive = current_consecutive
        start_day = start_day

    if max_consecutive == 0:
        return [0, None]
    else:
        return [max_consecutive, start_day]
