    # Sort rows by distance_km (descending), then day (ascending), then trip_id (ascending)
    sorted_rows = sorted(filtered_rows, key=lambda x: (-x['distance_km'], x['day'], x['trip_id']))

    # Initialize variables
    max_consecutive = 0
    current_consecutive = 0
    start_day = None

    # Track the earliest block on ties
    earliest_block = None

    for row in sorted_rows:
        if row['result'] == 'on_time' or row['result'] == 'aborted':
            if start_day is None:
                start_day = row['day']
                current_consecutive = 1
            else:
                current_consecutive += 1
            if current_consecutive > max_consecutive:
                max_consecutive = current_consecutive
                earliest_block = (start_day, start_day + current_consecutive - 1)
            elif current_consecutive == max_consecutive:
                if (start_day, start_day + current_consecutive - 1) < earliest_block:
                    earliest_block = (start_day, start_day + current_consecutive - 1)

    if max_consecutive == 0:
        return [0, None]
    else:
        return [max_consecutive, earliest_block[0]]
