def solve(rows):
    filtered_rows = [row for row in rows if row['day'] <= 20]
    from collections import defaultdict

    carrier_data = defaultdict(list)
    for row in filtered_rows:
        carrier = row['carrier']
        units = row['units']
        carrier_data[carrier].append(units)

    result = {}
    for carrier, units_list in carrier_data.items():
        units_list.sort()
        n = len(units_list)
        if n % 2 == 1:
            median = units_list[n // 2]
        else:
            median = (units_list[n // 2 - 1] + units_list[n // 2]) / 2
        result[carrier] = round(median, 1)

    return result
