def solve(rows):
    # Initialize balance and tracking variables
    balance = 0
    min_balance = None
    min_day = None

    # Process rows in ascending order (day, visit_id)
    for row in sorted(rows, key=lambda x: (x['day'], x['visit_id'])):
        if row['outcome'] == 'no_show':
            balance += row['duration_min']
        elif row['outcome'] == 'completed':
            balance -= row['duration_min']

        # Update min balance and day if a non-ignored row is processed
        if balance != 0:
            if min_balance is None or balance < min_balance:
                min_balance = balance
                min_day = row['day']
            elif balance == min_balance:
                if min_day is None or row['day'] < min_day:
                    min_day = row['day']

    # Return the result
    if min_balance is not None:
        return [min_balance, min_day]
    else:
        return [0, None]
