        if n % 2 == 1:
            median = (durations[n // 2] + durations[n // 2 + 1]) / 2
        else:
            median = (durations[n // 2 - 1] + durations[n // 2]) / 2

        # Round to one decimal place
        doctor_median[doctor] = round(median, 1)

    # Return the result
    return list(doctor_median.items())
