    # Filter rows where outcome is 'completed'
    completed_rows = [row for row in rows if row['outcome'] == 'completed']

    # Extract distinct day numbers
    days = sorted(set(row['day'] for row in completed_rows))

    if not days:
        return [0, None]

    max_length = 1
    current_length = 1
    start_day = days[0]
    current_start = days[0]

    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = current_start
            elif current_length == max_length:
                if current_start < start_day:
                    start_day = current_start
            current_length = 1
            current_start = days[i]

    # Check the last sequence
    if current_length > max_length:
        max_length = current_length
        start_day = current_start
    elif current_length == max_length:
        if current_start < start_day:
            start_day = current_start

    return [max_length, start_day]
