    filtered_rows = [row for row in rows if row['result'] != 'aborted']
    if not filtered_rows:
        return None

    depot_packages_distance = {}
    for row in filtered_rows:
        depot = row['depot']
        packages = row['packages']
        distance_km = row['distance_km']
        total = packages * distance_km
        if depot not in depot_packages_distance:
            depot_packages_distance[depot] = 0
        depot_packages_distance[depot] += total

    max_depot = None
    max_total = 0
    for depot, total in depot_packages_distance.items():
        if total > max_total or (total == max_total and depot < max_depot):
            max_total = total
            max_depot = depot

    return max_depot
