def solve(rows):
    filtered_rows = [row for row in rows if row['site'] in ['gwangju', 'incheon']]
    site_counts = {}
    for row in filtered_rows:
        site = row['site']
        if site not in site_counts:
            site_counts[site] = 0
        site_counts[site] += 1

    returned_rows = {}
    for row in filtered_rows:
        site = row['site']
        if site not in returned_rows:
            returned_rows[site] = 0
        returned_rows[site] += 1

    result = []
    for site in sorted(returned_rows.keys()):
        total = site_counts[site]
        returned = returned_rows[site]
        percentage = round(100 * (returned / total), 1)
        if percentage >= 20:
            result.append((percentage, site))

    result.sort(key=lambda x: (-x[0], x[1]))
    return result
