    if not days:
        return [0, None]

    sorted_days = sorted(days)
    max_length = 1
    start_day = sorted_days[0]

    for i in range(1, len(sorted_days)):
        if sorted_days[i] == sorted_days[i - 1] + 1:
            current_length = i - start_day + 1
            if current_length > max_length:
                max_length = current_length
                start_day = sorted_days[i - 1]
        elif sorted_days[i] != sorted_days[i - 1] + 1:
            start_day = sorted_days[i]

    return [max_length, start_day] if max_length > 0 else [0, None]
