def solve(rows):
    filtered_rows = [row for row in rows if row['site'] in ['gwangju', 'incheon']]
    if not filtered_rows:
        return None

    site_unit_weight_sum = {}
    for row in filtered_rows:
        site = row['site']
        units = row['units']
        weight_kg = row['weight_kg']
        key = (site, units, weight_kg)
        if key not in site_unit_weight_sum:
            site_unit_weight_sum[key] = 0
        site_unit_weight_sum[key] += units * weight_kg

    max_sum = -1
    selected_site = None
    for key, total in site_unit_weight_sum.items():
        site = key[0]
        if total > max_sum:
            max_sum = total
            selected_site = site
        elif total == max_sum:
            if site < selected_site:
                selected_site = site

    return selected_site
```

