    day_map = {}
    consecutive_days = []

    for row in rows:
        if row['phase'] == 'held':
            balance += row['units']
        elif row['phase'] == 'returned':
            balance -= row['units']
        elif row['weight_kg'] < 151:
            balance += row['units']

        if row['day'] not in day_map:
            day_map[row['day']] = 1
            consecutive_days = [row['day']]
        else:
            day_map[row['day']] += 1
            consecutive_days.append(row['day'])

        if balance != 0:
            if balance < min_balance:
                min_balance = balance
                min_day = day_map[row['day']]
            elif balance == min_balance:
                if day_map[row['day']] < min_day:
                    min_day = day_map[row['day']]

    if min_balance != float('inf'):
        return [len(consecutive_days), min_day]
    return [0, None]
