def solve(rows):
    filtered_rows = [row for row in rows if row['phase'] != 'held']
    if not filtered_rows:
        return {}
    carrier_units = {}
    for row in filtered_rows:
        carrier = row['carrier']
        units = row['units']
        if carrier not in carrier_units:
            carrier_units[carrier] = []
        carrier_units[carrier].append(units)
    result = {}
    for carrier, units_list in carrier_units.items():
        units_list.sort()
        n = len(units_list)
        if n == 0:
            continue
        if n % 2 == 1:
            median = units_list[n // 2]
        else:
            median = (units_list[n // 2 - 1] + units_list[n // 2]) / 2
        result[carrier] = round(median, 1)
    return result
```

