def solve(rows):
    # Filter rows where depot is 'alpha' or 'delta'
    filtered_rows = [row for row in rows if row['depot'] in ['alpha', 'delta']]

    # Group by driver and calculate median packages
    from statistics import median

    driver_packages = {}
    for row in filtered_rows:
        driver = row['driver']
        packages = row['packages']
        if driver in driver_packages:
            driver_packages[driver].append(packages)
        else:
            driver_packages[driver] = [packages]

    # Calculate median for each driver
    result_dict = {}
    for driver, packages in driver_packages.items():
        n = len(packages)
        if n % 2 == 1:
            median_packages = median(packages)
        else:
            median_packages = (median(packages) + median(packages[1:])) / 2
        result_dict[driver] = round(median_packages, 1)

    return result_dict
```

